# Paste into Azure portal > VM > Run command > RunShellScript. Runs as root.
# READ-ONLY with respect to the books: it installs rebuild_equity.py and reads the trade
# CSVs. It writes no state, touches no equity, and does not restart anything - so it is
# safe to run at any time, before or after patch_entry_sized.sh.
#
# It rebuilds each book's equity curve under the ENTRY-SIZED convention (mistake #14) from
# R and risk_pct, which the log records and which no accounting choice can change. It first
# replays the OLD convention and checks that reproduces the log's own equity column; if that
# check fails it says so and the corrected numbers must not be trusted.
# No backslashes on purpose: Run command JSON-decodes the script and would corrupt them.
set -e
APP=/opt/forexbot
cd $APP
echo '' | base64 -d | gunzip > rebuild_equity.py.new
echo "e2bc652a54ed5654bd380b05c043e8ae19697ee36e7a6778c2adcb013abc7b36  rebuild_equity.py.new" | sha256sum -c -
./.venv/bin/python -c "import ast; ast.parse(open('rebuild_equity.py.new').read()); print('syntax ok')"
OWNER=$(stat -c %U blend_paper.py)
mv rebuild_equity.py.new rebuild_equity.py
chown $OWNER:$OWNER rebuild_equity.py
echo "installed rebuild_equity.py"
wc -l logs/trades_blend*.csv || true
./.venv/bin/python rebuild_equity.py --show-ambiguity
echo "--- writing the corrected curves to logs/corrected_*.csv ---"
./.venv/bin/python rebuild_equity.py --csv logs/corrected.csv > /dev/null
ls -la logs/corrected_*.csv || true
chown $OWNER:$OWNER logs/corrected_*.csv || true
